update tbl_title set
	staff_id = #{staff_id}
	,ttl_serial = #{ttl_serial}
	,ttl_name = #{ttl_name}
	,ttl_platform = #{ttl_platform}
	,ttl_genre = #{ttl_genre}
	,ttl_stock = #{ttl_stock}
	,ttl_price = #{ttl_price}
	,ttl_thumbnail = #{ttl_thumbnail}
	,ttl_state = #{ttl_state}
	,ttl_moddate = now()
where ttl_serial = #{ttl_serial}
